.page {
  width: 100%;
  max-width: 560px;
}

.page-header {
  margin-bottom: 2rem;
}

.page-header .eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 0.5rem;
}

.page-header h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  color: var(--color-text-primary);
  line-height: 1.2;
}

.page-header .subtitle {
  margin-top: 0.5rem;
  color: var(--color-text-secondary);
  font-size: 0.9375rem;
}

/* ── Card ───────────────────────────────────────────────── */
.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  box-shadow: var(--shadow-card);
}

/* ── Required legend ────────────────────────────────────── */
.required-note {
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  margin-bottom: 1.5rem;
}
.required-note .req-star {
  color: var(--color-required);
  font-weight: 700;
  margin-right: 0.15em;
}

/* ── Form fields ────────────────────────────────────────── */
.form-field {
  margin-bottom: 1.25rem;
}

.form-field:last-of-type {
  margin-bottom: 1.75rem;
}

.form-field label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text-primary);
  margin-bottom: 0.4rem;
}

.form-field label .req-star {
  color: var(--color-required);
  margin-left: 0.15em;
  font-weight: 700;
  aria-hidden: true;
}

.field-optional {
  font-size: 0.75rem;
  font-weight: 400;
  color: var(--color-text-secondary);
  margin-left: 0.4rem;
}

.form-field input {
  display: block;
  width: 100%;
  padding: 0.65rem 0.875rem;
  background: var(--color-surface-raised);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text-primary);
  font-size: 0.9375rem;
  font-family: inherit;
  line-height: 1.5;
  transition: border-color var(--transition), box-shadow var(--transition);
  outline: none;
}

.form-field input::placeholder {
  color: var(--color-text-placeholder);
}

.form-field input:focus {
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(108, 142, 245, 0.25);
  outline: 2px solid transparent; /* visible via box-shadow + border */
}

/* forced-colors fallback */
@media (forced-colors: active) {
  .form-field input:focus {
    outline: 2px solid ButtonText;
  }
}

.form-field input[aria-invalid="true"] {
  border-color: var(--color-border-error);
}

.form-field input[aria-invalid="true"]:focus {
  border-color: var(--color-border-error);
  box-shadow: 0 0 0 3px rgba(240, 94, 94, 0.25);
}

/* ── Helper / error text ────────────────────────────────── */
.field-hint {
  display: flex;
  align-items: flex-start;
  gap: 0.3rem;
  margin-top: 0.35rem;
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  line-height: 1.4;
}

.field-error {
  display: none;
  align-items: flex-start;
  gap: 0.3rem;
  margin-top: 0.35rem;
  font-size: 0.8125rem;
  color: var(--color-error);
  line-height: 1.4;
  font-weight: 500;
}

.field-error.is-visible {
  display: flex;
}

.field-error svg,
.field-hint svg {
  flex-shrink: 0;
  margin-top: 1px;
}

/* ── Submit button ──────────────────────────────────────── */
.btn-submit {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition), transform 80ms ease;
  outline: none;
}

.btn-submit:hover {
  background: var(--color-accent-hover);
}

.btn-submit:focus-visible {
  box-shadow: 0 0 0 3px rgba(108, 142, 245, 0.4);
  outline: 2px solid transparent;
}

@media (forced-colors: active) {
  .btn-submit:focus-visible {
    outline: 2px solid ButtonText;
  }
}

.btn-submit:active {
  transform: translateY(1px);
}

.btn-submit:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

/* ── Status banner ──────────────────────────────────────── */
.status-banner {
  display: none;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 500;
  margin-bottom: 1.5rem;
  line-height: 1.4;
}

.status-banner.is-visible {
  display: flex;
}

.status-banner.is-success {
  background: rgba(78, 205, 196, 0.12);
  border: 1px solid rgba(78, 205, 196, 0.35);
  color: var(--color-success);
}

.status-banner.is-error {
  background: rgba(240, 94, 94, 0.1);
  border: 1px solid rgba(240, 94, 94, 0.3);
  color: var(--color-error);
}

.status-banner svg {
  flex-shrink: 0;
  margin-top: 1px;
}

/* ── Divider ────────────────────────────────────────────── */
.divider {
  height: 1px;
  background: var(--color-border);
  margin: 1.5rem 0;
}

/* ── Reflow ─────────────────────────────────────────────── */
@media (max-width: 400px) {
  .card {
    padding: 1.25rem;
  }
}
