(function () {
  "use strict";

  /* ── Field definitions ──────────────────────────────────────────────── */
  const FIELDS = [
    {
      id: "field-name",
      inputId: "input-name",
      errorId: "error-name",
      hintId: null,
      required: true,
      validate(value) {
        if (!value.trim()) return "Full name is required.";
        if (value.trim().length < 2) return "Please enter your full name (at least 2 characters).";
        return null;
      },
    },
    {
      id: "field-email",
      inputId: "input-email",
      errorId: "error-email",
      hintId: null,
      required: true,
      validate(value) {
        if (!value.trim()) return "Email address is required.";
        // RFC 5322 simplified check
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()))
          return "Please enter a valid email address (e.g. you@example.com).";
        return null;
      },
    },
    {
      id: "field-phone",
      inputId: "input-phone",
      errorId: "error-phone",
      hintId: "hint-phone",
      required: false,
      validate(value) {
        if (!value.trim()) return null; // optional
        // Accepts formats: +1 (555) 000-0000, 555-000-0000, 5550000000, etc.
        if (!/^[+]?[\d\s\-().]{7,20}$/.test(value.trim()))
          return "Please enter a valid phone number (digits, spaces, hyphens, and parentheses only).";
        return null;
      },
    },
  ];

  /* ── State ──────────────────────────────────────────────────────────── */
  let hasSubmitted = false; // track whether user has hit Submit at least once

  /* ── Helpers ────────────────────────────────────────────────────────── */
  function getInput(field) {
    return document.getElementById(field.inputId);
  }

  function getErrorEl(field) {
    return document.getElementById(field.errorId);
  }

  function showError(field, message) {
    const input = getInput(field);
    const errorEl = getErrorEl(field);
    if (!input || !errorEl) return;

    input.setAttribute("aria-invalid", "true");
    errorEl.textContent = message;
    errorEl.classList.add("is-visible");
  }

  function clearError(field) {
    const input = getInput(field);
    const errorEl = getErrorEl(field);
    if (!input || !errorEl) return;

    input.removeAttribute("aria-invalid");
    errorEl.textContent = "";
    errorEl.classList.remove("is-visible");
  }

  function validateField(field) {
    const input = getInput(field);
    if (!input) return null;
    const error = field.validate(input.value);
    if (error) {
      showError(field, error);
    } else {
      clearError(field);
    }
    return error;
  }

  /* ── Live re-validation (only after first submit) ───────────────────── */
  function attachBlurListeners() {
    FIELDS.forEach((field) => {
      const input = getInput(field);
      if (!input) return;
      input.addEventListener("blur", () => {
        if (hasSubmitted) validateField(field);
      });
      input.addEventListener("input", () => {
        if (hasSubmitted) validateField(field);
      });
    });
  }

  /* ── Status banner ──────────────────────────────────────────────────── */
  function showStatus(type, message) {
    const banner = document.getElementById("status-banner");
    if (!banner) return;
    banner.className = `status-banner is-visible is-${type}`;
    banner.querySelector(".status-text").textContent = message;
    // Swap icon visibility
    banner.querySelectorAll("[data-icon]").forEach((el) => {
      el.hidden = el.dataset.icon !== type;
    });
  }

  function hideStatus() {
    const banner = document.getElementById("status-banner");
    if (!banner) return;
    banner.className = "status-banner";
    banner.querySelector(".status-text").textContent = "";
  }

  /* ── Submit handler ─────────────────────────────────────────────────── */
  function handleSubmit(e) {
    e.preventDefault();
    hasSubmitted = true;
    hideStatus();

    const errors = FIELDS.map((field) => validateField(field)).filter(Boolean);

    if (errors.length > 0) {
