      hasSubmitted = false;
      FIELDS.forEach((f) => clearError(f));
    }, 1200);
  }

  /* ── Init ───────────────────────────────────────────────────────────── */
  document.addEventListener("DOMContentLoaded", () => {
    const form = document.getElementById("contact-form");
    if (form) form.addEventListener("submit", handleSubmit);
    attachBlurListeners();
  });
